import { readFileSync } from 'node:fs';
import { z } from 'zod';
import { renderToolReference, TOOLS_PATH } from '../../scripts/docs/tools.js';
import { allTools } from '../../src/tools/index.js';
import { toolProfiles } from '../../src/tools/schema-export.js';
import { defineTool, type AnyToolDefinition } from '../../src/tools/types.js';

// docs/tools.md lists every tool with its inputs, generated by `pnpm docs:tools` from the tool
// definitions. These tests fail when it has fallen behind them.

const page = renderToolReference(allTools);

function readText(path: string): string {
  return readFileSync(path, 'utf8').replaceAll('\r\n', '\n');
}

function firstDifference(committed: string, generated: string): string {
  const committedLines = committed.split('\n');
  const generatedLines = generated.split('\n');
  const count = Math.max(committedLines.length, generatedLines.length);
  for (let index = 0; index < count; index += 1) {
    if (committedLines[index] !== generatedLines[index]) {
      return (
        `First difference at line ${String(index + 1)}:\n` +
        `  committed: ${committedLines[index] ?? '(the file ends)'}\n` +
        `  generated: ${generatedLines[index] ?? '(the page ends)'}`
      );
    }
  }
  return 'The texts differ.';
}

describe('docs/tools.md', () => {
  test('docs/tools.md is up to date', () => {
    let committed: string;
    try {
      committed = readText(TOOLS_PATH);
    } catch {
      throw new Error(
        'docs/tools.md does not exist. Run `pnpm docs:tools` to generate it, then commit it.',
      );
    }

    if (committed !== page) {
      throw new Error(
        'docs/tools.md is out of date. Run `pnpm docs:tools` and commit the result.\n' +
          firstDifference(committed, page),
      );
    }
  });

  test('the tool reference lists every tool once under its domain with the computed totals', () => {
    const core = allTools.filter((tool) => toolProfiles(tool).includes('core')).length;
    const readonly = allTools.filter((tool) => toolProfiles(tool).includes('readonly')).length;

    expect(page).toContain(
      `${String(allTools.length)} tools: ${String(core)} in the core profile, ${String(readonly)} in the readonly profile.`,
    );
    expect(page).toContain('Generated by `pnpm docs:tools` from the tool definitions.');

    const headings = [...page.matchAll(/^### (\S+)$/gm)].map((match) => match[1]);
    expect(headings).toEqual(allTools.map(({ name }) => name));

    // Each tool sits under the section of its domain, in the order of the catalogue.
    const sections = page.split(/^## /m).slice(1);
    const domains = [...new Set(allTools.map(({ domain }) => domain))];
    expect(sections).toHaveLength(domains.length);
    for (const [index, domain] of domains.entries()) {
      const tools = allTools.filter((tool) => tool.domain === domain);
      const section = sections[index] ?? '';
      expect(section.split('\n')[0]).toMatch(new RegExp(`\\(${String(tools.length)} tools?\\)$`));
      expect([...section.matchAll(/^### (\S+)$/gm)].map((match) => match[1])).toEqual(
        tools.map(({ name }) => name),
      );
    }
  });

  test('the output is the same on every render', () => {
    expect(renderToolReference(allTools)).toBe(page);
    expect(page.endsWith('\n')).toBe(true);
    expect(page).not.toContain('\r');
  });

  function fake(name: string, shape: z.ZodRawShape, description: string): AnyToolDefinition {
    return defineTool({
      name,
      domain: 'chart',
      title: `Title of ${name}`,
      description,
      inputSchema: shape,
      annotations: { readOnlyHint: true, idempotentHint: true },
      core: true,
      handler: () => Promise.resolve({ data: null }),
    });
  }

  test('a tool with no inputs says No inputs and table cells escape pipes and newlines', () => {
    const text = renderToolReference([
      fake('chart_nothing', {}, 'First paragraph.\n\nSecond | paragraph.'),
      fake('chart_cell', { mode: z.string().describe('Either a | b,\nor c.') }, 'Has one input.'),
    ]);

    const nothing = text.split('### chart_nothing')[1]?.split('### chart_cell')[0] ?? '';
    expect(nothing).toContain('No inputs.');
    expect(nothing).not.toContain('| Input |');
    // Paragraphs of a description stay paragraphs, and are not escaped.
    expect(nothing).toContain('First paragraph.\n\nSecond | paragraph.');

    const cell = text.split('### chart_cell')[1] ?? '';
    expect(cell).toContain('| `mode` | string | yes | Either a \\| b,<br>or c. |');
    expect(cell).toContain('`Read-only`');
    expect(cell).toContain('`Idempotent`');
    expect(cell).toContain('`core`');
    expect(cell).not.toContain('`Destructive`');
  });

  test('types, constraints, enums and defaults are named readably, not dumped as JSON Schema', () => {
    const text = renderToolReference([
      fake(
        'chart_types',
        {
          kind: z.enum(['a', 'b']).describe('The kind.'),
          size: z.number().int().min(1).max(4).default(2).describe('The size.'),
          label: z.string().min(1).max(20).optional().describe('The label.'),
          points: z
            .array(z.object({ time: z.union([z.string(), z.number()]), price: z.number() }))
            .min(1)
            .max(10)
            .describe('The points.'),
          extra: z.record(z.string(), z.unknown()).optional().describe('Anything.'),
        },
        'Typed.',
      ),
    ]);

    expect(text).toContain('| `kind` | string | yes | The kind. One of: `a`, `b`. |');
    expect(text).toContain('| `size` | integer | no | The size. 1 to 4. Default: `2`. |');
    expect(text).toContain('| `label` | string | no | The label. 1 to 20 characters. |');
    expect(text).toContain('| `points` | object[] | yes | The points. 1 to 10 items. Fields: ');
    expect(text).toContain('`time` (string or number, required)');
    expect(text).toContain('| `extra` | object | no | Anything. |');
    expect(text).not.toContain('"type"');
  });

  test('the real nested inputs read as types', () => {
    expect(page).toMatch(/\| `steps` \| object\[\] \| yes \|/);
    expect(page).toMatch(/\| `points` \| object\[\] \| yes \|/);
    expect(page).not.toContain('anyOf');
    expect(page).not.toContain('additionalProperties');
  });
});
